# NeurIPS, ICML, AAAI. Years are ints. test_of_time uses tot=True.

def P(conference, year, award, title, authors, url, domain, did, insight, why, tot=False, original_year=None):
    row = {
        "conference": conference, "year": year, "award": award, "title": title,
        "authors": authors, "url": url, "domain": domain, "did": did,
        "insight": insight, "why": why,
    }
    if tot:
        row["test_of_time"] = True
        row["original_year"] = original_year
    return row

